#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// TILE_SIZE must be divisible by UNROLL_FACTOR
#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int N
) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Starting indices
    int row_start = by * TILE_SIZE;
    int col_start = bx * TILE_SIZE;

    // Register accumulators
    float accum[TILE_SIZE / UNROLL_FACTOR][TILE_SIZE / UNROLL_FACTOR] = {{0}};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Preload next tile
        int a_row = row_start + ty;
        int a_col = t * TILE_SIZE + tx;
        As[ty][tx] = (a_row < N && a_col < N) ? A[a_row * N + a_col] : 0.0f;

        int b_row = t * TILE_SIZE + ty;
        int b_col = col_start + tx;
        Bs[ty][tx] = (b_row < N && b_col < N) ? B[b_row * N + b_col] : 0.0f;

        __syncthreads();

        // Compute partial dot product with unrolling
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            // Prefetch next elements
            float a_vals[UNROLL_FACTOR];
            float b_vals[UNROLL_FACTOR];

            #pragma unroll
            for (int u = 0; u < UNROLL_FACTOR; u++) {
                a_vals[u] = As[ty][k + u];
                b_vals[u] = Bs[k + u][tx];
            }

            // Accumulate with unrolling
            #pragma unroll
            for (int u = 0; u < UNROLL_FACTOR; u++) {
                accum[ty / UNROLL_FACTOR][tx / UNROLL_FACTOR] += a_vals[u] * b_vals[u];
            }
        }

        __syncthreads();
    }

    // Write result to global memory
    int out_row = row_start + ty;
    int out_col = col_start + tx;
    if (out_row < N && out_col < N) {
        C[out_row * N + out_col] = accum[ty / UNROLL_FACTOR][tx / UNROLL_FACTOR];
    }
